/**
 * Autorender upload proxy — standalone service for apps with NO server of their own.
 *
 * A Vite SPA — and anything generated by Lovable, v0 or Bolt — has no route handler,
 * so there is nowhere inside the app for the API key to live. The key belongs in a
 * backend you control. This is that backend: one file with no external dependency.
 *
 * ⚠️ Memory: on Node 24, `fetch()` with a FormData body containing a File retains the
 * payload — measured at ~72 MB retained per wave of 8 concurrent 9 MB uploads, not
 * released by GC. Node 20 plateaus correctly. Until that is resolved upstream, run
 * this on Node 20 or 22, keep MAX_CONCURRENT low, and give the container headroom of
 * at least MAX_CONCURRENT x MAX_BYTES x 3.
 *
 *   AUTORENDER_API_KEY=…  ALLOWED_ORIGIN=https://app.example.com  node standalone-service.mjs
 *
 * This is a LONG-LIVED HTTP SERVER, not a serverless function. Function runtimes
 * (Vercel, Netlify, Cloudflare Workers, Supabase Edge) export a handler instead of
 * calling `listen()`. Porting means REWRITING the I/O: every `json(res, …)`, the
 * header reads, and the `for await (const chunk of req)` loop are Node-specific,
 * while those runtimes speak `Request`/`Response`. What must survive the rewrite is
 * the logic, in this order: authenticate, rate limit, size check, parse, validate the
 * bytes, sanitize the name, then forward with a session-derived folder. Copy the
 * order, not the plumbing.
 *
 * Auth here is a BEARER TOKEN, deliberately. Cookie auth across origins needs
 * `Access-Control-Allow-Credentials: true` on every response plus
 * `xhr.withCredentials = true` in the browser plus `SameSite=None; Secure` on the
 * cookie. Getting one of those wrong fails in a way whose usual "fix" is to widen
 * CORS to a wildcard, which turns this into an open proxy. Bearer avoids the trap.
 */

import { createServer } from 'node:http';

const UPLOAD_BASE = process.env.AUTORENDER_UPLOAD_BASE_URL ?? 'https://upload.autorender.io';
const UPLOAD_URL = `${UPLOAD_BASE}/api/v1/uploads`;

const MAX_BYTES = 10 * 1024 * 1024;

/**
 * Ceiling for the whole multipart envelope, which is necessarily larger than the file
 * inside it: every part carries a boundary and headers. Holding the envelope to
 * MAX_BYTES would reject a legitimate MAX_BYTES file because of its own framing.
 */
const MAX_BODY_BYTES = MAX_BYTES + 64 * 1024;

const MAX_CONCURRENT = 4; // peak memory is roughly MAX_CONCURRENT x MAX_BYTES x 3
const UPSTREAM_TIMEOUT_MS = 30_000;

/**
 * A size cap bounds how much a caller sends, not how long they take: one byte every
 * few seconds stays under any ceiling indefinitely while holding a slot, and with only
 * MAX_CONCURRENT slots that is all it takes to stall the service. Node's own default
 * is 300s per request, which is far too generous for an upload this size.
 *
 * Unrelated to UPSTREAM_TIMEOUT_MS above despite the similar value — this bounds
 * RECEIVING from the client, that one bounds FORWARDING to Autorender.
 *
 * Note this is a TOTAL budget, unlike the Next.js route's idle-based BODY_IDLE_MS:
 * Node offers no idle-body timeout, so it is the blunter of the two instruments. That
 * makes it a floor on throughput — MAX_BODY_BYTES / this ≈ 88 kB/s (~0.7 Mbps) — so
 * RAISE IT IF YOU RAISE MAX_BYTES, or slow mobile clients will be cut off mid-upload.
 */
const REQUEST_TIMEOUT_MS = 120_000;

const API_KEY = process.env.AUTORENDER_API_KEY;
const ALLOWED_ORIGIN = process.env.ALLOWED_ORIGIN;
const PORT = Number(process.env.PORT ?? 8787);

if (!API_KEY) throw new Error('AUTORENDER_API_KEY is required');
if (!ALLOWED_ORIGIN) throw new Error('ALLOWED_ORIGIN is required — do not ship a wildcard');
// Refuse the wildcard rather than warning about it. With `*` this would be an open
// upload proxy on an unscoped key, and the origin check below would then reject every
// real browser anyway, so it is never what you want.
if (ALLOWED_ORIGIN === '*') throw new Error('ALLOWED_ORIGIN must be an exact origin, not "*"');
if (!Number.isInteger(PORT) || PORT < 1 || PORT > 65535) throw new Error(`PORT is invalid: ${process.env.PORT}`);

/**
 * Magic bytes per claimed type — see the long note in app-router-upload-route.ts.
 * A Map, not an object literal: object lookup walks the prototype chain, so a
 * `Content-Type` of `constructor` or `toString` would return an inherited function
 * and pass the guard.
 */
const SIGNATURES = new Map([
  ['image/jpeg', (b) => b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff],
  ['image/png', (b) => b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47],
  [
    'image/webp',
    (b) =>
      b[0] === 0x52 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x46 &&
      b[8] === 0x57 && b[9] === 0x45 && b[10] === 0x42 && b[11] === 0x50,
  ],
  [
    // Bytes 0..3 are the box length and MUST be checked — see the note in
    // app-router-upload-route.ts.
    'image/avif',
    (b, size) => {
      const boxSize = ((b[0] << 24) | (b[1] << 16) | (b[2] << 8) | b[3]) >>> 0;
      if (boxSize < 16 || boxSize > size) return false;
      const tag = String.fromCharCode(b[4], b[5], b[6], b[7]);
      const brand = String.fromCharCode(b[8], b[9], b[10], b[11]);
      return tag === 'ftyp' && (brand === 'avif' || brand === 'avis');
    },
  ],
]);

const EXTENSION = new Map([
  ['image/jpeg', 'jpg'],
  ['image/png', 'png'],
  ['image/webp', 'webp'],
  ['image/avif', 'avif'],
]);

/** `file.name` is client-controlled: basename it, allowlist it, force the extension. */
function safeFileName(rawName, mime) {
  const base = String(rawName ?? '').split(/[\\/]/).pop() ?? '';
  const stem = base
    .replace(/\.[^.]*$/, '')
    .replace(/[^A-Za-z0-9._-]/g, '_')
    .replace(/^[.]+/, '')
    .slice(0, 100);
  return `${stem || 'upload'}.${EXTENSION.get(mime)}`;
}

/**
 * Replace with your real auth. Return null when the caller is not signed in;
 * throwing is handled too, so either contract fails closed.
 *
 * `userId` should be an opaque identifier — not an email — and must not contain `/`,
 * since it becomes part of the storage folder.
 */
async function authenticate(req) { // eslint-disable-line no-unused-vars
  throw new Error('Wire this to your auth before deploying. An open proxy is an open wallet.');
}

/**
 * Rate limit per caller. The upstream limit is 60 requests per 10 seconds PER
 * WORKSPACE, so without this one abuser starves every user of your app.
 *
 * In-memory, so it is per-instance: behind more than one replica, move it to Redis
 * or your database.
 */
const BUCKET_CAPACITY = 10;
const BUCKET_REFILL_PER_MS = 10 / 10_000; // 10 tokens per 10s
const buckets = new Map();

function takeToken(key) {
  const now = Date.now();
  const bucket = buckets.get(key) ?? { tokens: BUCKET_CAPACITY, updated: now };
  bucket.tokens = Math.min(BUCKET_CAPACITY, bucket.tokens + (now - bucket.updated) * BUCKET_REFILL_PER_MS);
  bucket.updated = now;
  if (bucket.tokens < 1) {
    buckets.set(key, bucket);
    return false;
  }
  bucket.tokens -= 1;
  buckets.set(key, bucket);
  return true;
}

// Bound the map so a stream of distinct identities cannot grow it without limit.
setInterval(() => {
  const cutoff = Date.now() - 60_000;
  for (const [key, bucket] of buckets) if (bucket.updated < cutoff) buckets.delete(key);
}, 60_000).unref();

function corsHeaders(req) {
  return {
    'Access-Control-Allow-Origin': ALLOWED_ORIGIN,
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    // Reflect the browser's own list rather than hardcoding one: a platform client
    // SDK adds headers of its own, and omitting any single one fails the preflight
    // before your code runs.
    'Access-Control-Allow-Headers': req.headers['access-control-request-headers'] ?? 'authorization, content-type',
    'Access-Control-Max-Age': '86400',
    Vary: 'Origin',
  };
}

const json = (res, status, body, extra = {}) => {
  res.writeHead(status, { 'Content-Type': 'application/json', ...extra });
  res.end(JSON.stringify(body));
};

let inFlight = 0;

async function handleUpload(req, res, cors) {
  let session;
  try {
    session = await authenticate(req);
  } catch (cause) {
    // Log it: once wired, a database outage or a bug in the reader must be
    // distinguishable from a genuine rejection.
    console.error('autorender upload proxy: auth failed', cause);
    return json(res, 401, { error: 'Unauthorized' }, cors);
  }
  // A null return is the documented contract, and must fail closed exactly like a
  // throw. Omitting this check is an unauthenticated crash, not just a 500.
  if (!session?.userId) {
    return json(res, 401, { error: 'Unauthorized' }, cors);
  }

  // The folder is built from this, so a userId containing `/` would climb out of the
  // per-user prefix. Enforce it rather than only documenting it.
  if (typeof session.userId !== 'string' || !/^[A-Za-z0-9_-]{1,64}$/.test(session.userId)) {
    console.error('autorender upload proxy: userId is not an opaque token');
    return json(res, 500, { error: 'Upload failed' }, cors);
  }

  if (!takeToken(session.userId)) {
    return json(res, 429, { error: 'Too many uploads' }, { ...cors, 'Retry-After': '10' });
  }

  // Fast path only: a body that admits to being oversized, rejected without a read.
  const declaredLength = Number(req.headers['content-length'] ?? '0');
  if (Number.isFinite(declaredLength) && declaredLength > MAX_BODY_BYTES) {
    return json(res, 413, { error: 'Request body too large' }, cors);
  }

  // Buffer with a hard ceiling, enforced as chunks arrive so an oversized body is
  // never fully committed to memory. Compared against MAX_BODY_BYTES, not MAX_BYTES:
  // this counts the whole multipart envelope, and a legitimate MAX_BYTES file plus its
  // own boundary and part headers is larger than MAX_BYTES. The file itself is still
  // held to MAX_BYTES once parsed, below.
  const chunks = [];
  let total = 0;
  for await (const chunk of req) {
    total += chunk.length;
    if (total > MAX_BODY_BYTES) {
      return json(res, 413, { error: 'Request body too large' }, cors);
    }
    chunks.push(chunk);
  }

  let incoming;
  try {
    incoming = await new Request('http://localhost', {
      method: 'POST',
      headers: { 'content-type': req.headers['content-type'] ?? '' },
      body: Buffer.concat(chunks),
    }).formData();
  } catch {
    return json(res, 400, { error: 'Expected multipart/form-data' }, cors);
  }

  const file = incoming.get('file');
  if (!(file instanceof File)) {
    return json(res, 400, { error: 'Expected a file in the "file" field' }, cors);
  }
  // The stream ceiling above is the ENVELOPE (MAX_BODY_BYTES); this holds the FILE to
  // MAX_BYTES. Both are needed — neither implies the other.
  if (file.size > MAX_BYTES) {
    return json(res, 413, { error: 'File too large' }, cors);
  }

  const signature = SIGNATURES.get(file.type);
  const header = new Uint8Array(await file.slice(0, 16).arrayBuffer());
  if (!signature || !signature(header, file.size)) {
    console.warn('autorender upload rejected: type/bytes mismatch', file.type);
    return json(res, 415, { error: 'Unsupported or malformed image' }, cors);
  }

  const form = new FormData();
  form.append('file', file);
  form.append('file_name', safeFileName(file.name, file.type)); // REQUIRED
  form.append('folder', `users/${session.userId}`); // from the session, never the body
  form.append('random_prefix', 'true'); // else a repeated name replaces the asset

  const upstream = await fetch(UPLOAD_URL, {
    method: 'POST',
    headers: { Authorization: `Bearer ${API_KEY}` },
    body: form,
    signal: AbortSignal.timeout(UPSTREAM_TIMEOUT_MS),
  });

  // Forward 429: the upstream limit is per workspace, so the caller needs to back off.
  if (upstream.status === 429) {
    return json(res, 429, { error: 'Rate limited' }, {
      ...cors,
      'Retry-After': upstream.headers.get('retry-after') ?? '10',
    });
  }

  if (!upstream.ok) {
    console.error('autorender upload failed', upstream.status, await upstream.text());
    return json(res, 502, { error: 'Upload failed' }, cors);
  }

  const asset = await upstream.json();
  return json(
    res,
    201, // matches what the upstream returns
    {
      file_no: asset.file_no,
      path: asset.path,
      url: asset.url,
      width: asset.width,
      height: asset.height,
    },
    cors,
  );
}

const server = createServer(async (req, res) => {
  const cors = corsHeaders(req);

  // Any throw below would otherwise be an unhandled rejection, and Node exits on
  // those — one malformed request would take the service down for everyone.
  try {
    if (req.method === 'OPTIONS') {
      res.writeHead(204, cors);
      return res.end();
    }
    if (req.method !== 'POST') {
      return json(res, 405, { error: 'Method not allowed' }, cors);
    }
    // A malformed target (`//`, `http://`) makes `new URL` throw, which would surface
    // as a 500 for what is really a bad request.
    let pathname;
    try {
      pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
    } catch {
      return json(res, 404, { error: 'Not found' }, cors);
    }
    if (pathname !== '/') {
      return json(res, 404, { error: 'Not found' }, cors);
    }
    // An origin check is a browser convenience, not an auth control — a non-browser
    // client simply omits the header. Authentication is the boundary.
    if (req.headers.origin && req.headers.origin !== ALLOWED_ORIGIN) {
      return json(res, 403, { error: 'Forbidden origin' }, cors);
    }
    if (inFlight >= MAX_CONCURRENT) {
      return json(res, 503, { error: 'Busy, retry shortly' }, { ...cors, 'Retry-After': '2' });
    }

    inFlight++;
    try {
      await handleUpload(req, res, cors);
    } finally {
      inFlight--;
    }
  } catch (cause) {
    console.error('autorender upload proxy error', cause);
    if (!res.headersSent) json(res, 500, { error: 'Upload failed' }, cors);
    else res.end();
  }
});

// Bound how long a request may take, not just how large it may be. Without this a
// trickle of bytes occupies a concurrency slot for Node's default 300s. Node responds
// 408 and closes the socket itself when this trips — the same status the Next.js route
// returns explicitly from its own body limiter (cf. BODY_IDLE_MS there).
server.requestTimeout = REQUEST_TIMEOUT_MS;
server.headersTimeout = 10_000; // Node's default here is 60s

server.listen(PORT, () => {
  console.log(`autorender upload proxy on :${PORT}, allowing ${ALLOWED_ORIGIN}`);
});

// Last-resort backstop so an unforeseen rejection logs instead of exiting.
process.on('unhandledRejection', (cause) => console.error('unhandled rejection', cause));
